namespace sv_27be7b54d345427bb58daf0a808ced11.Services;

public class DoctorInfo
{
    public string Name { get; set; } = string.Empty;
    public bool AcceptsSelfPay { get; set; }
}

public class ValidationResult
{
    public bool IsValid => Errors.Count == 0;
    public Dictionary<string, string> Errors { get; } = new();
}

public class AppointmentService
{
    private static readonly List<DoctorInfo> Doctors =
    [
        new() { Name = "Dr. Smith", AcceptsSelfPay = false },
        new() { Name = "Dr. Johnson", AcceptsSelfPay = true },
        new() { Name = "Dr. Patel", AcceptsSelfPay = true },
        new() { Name = "Dr. Williams", AcceptsSelfPay = false },
    ];

    private static readonly List<string> AllSlots =
    [
        "9:00 AM", "9:30 AM", "10:00 AM", "10:30 AM",
        "11:00 AM", "11:30 AM", "1:00 PM", "1:30 PM",
        "2:00 PM", "2:30 PM", "3:00 PM", "3:30 PM",
    ];

    public Task<List<DoctorInfo>> GetDoctorsAsync()
    {
        return Task.FromResult(new List<DoctorInfo>(Doctors));
    }

    public Task<List<string>> GetAvailableSlotsAsync(string doctorName, DateOnly date)
    {
        // Stub: return all slots for any valid doctor + future date
        return Task.FromResult(new List<string>(AllSlots));
    }

    public Task<ValidationResult> ValidatePatientAsync(
        string email, string insuranceProvider, string doctorName, string? timeSlot)
    {
        var result = new ValidationResult();

        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            result.Errors["Email"] = "Account has outstanding balance";
        }

        if (string.Equals(insuranceProvider, "None", StringComparison.Ordinal))
        {
            var doctor = Doctors.FirstOrDefault(d => d.Name == doctorName);
            if (doctor is { AcceptsSelfPay: false })
            {
                result.Errors["PreferredDoctor"] = "Selected doctor does not accept self-pay patients";
            }
        }

        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            result.Errors["TimeSlot"] = "This slot is no longer available";
        }

        return Task.FromResult(result);
    }
}

using System.ComponentModel.DataAnnotations;

namespace sv_27be7b54d345427bb58daf0a808ced11.Models;

public class AppointmentModel
{
    // Step 1
    [Required(ErrorMessage = "Patient name is required.")]
    public string PatientName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Invalid email format.")]
    public string Email { get; set; } = string.Empty;

    [Required(ErrorMessage = "Phone number is required.")]
    [Phone(ErrorMessage = "Invalid phone number.")]
    public string Phone { get; set; } = string.Empty;

    [Required(ErrorMessage = "Insurance provider is required.")]
    public string InsuranceProvider { get; set; } = string.Empty;

    // Step 2
    [Required(ErrorMessage = "Please select a doctor.")]
    public string PreferredDoctor { get; set; } = string.Empty;

    [Required(ErrorMessage = "Date is required.")]
    public DateOnly? AppointmentDate { get; set; }

    [Required(ErrorMessage = "Please select a time slot.")]
    public string TimeSlot { get; set; } = string.Empty;

    [Required(ErrorMessage = "Reason for visit is required.")]
    [MaxLength(500, ErrorMessage = "Reason cannot exceed 500 characters.")]
    public string ReasonForVisit { get; set; } = string.Empty;
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_27be7b54d345427bb58daf0a808ced11.Models
@using sv_27be7b54d345427bb58daf0a808ced11.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book a Medical Appointment</h3>

<EditForm EditContext="editContext" OnValidSubmit="HandleSubmit" FormName="appointment">
    <DataAnnotationsValidator />

    @* ───── STEP 1 ───── *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="model.PatientName" />
            <ValidationMessage For="() => model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="model.Email" />
            <ValidationMessage For="() => model.Email" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="model.Phone" />
            <ValidationMessage For="() => model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => model.InsuranceProvider" />
        </div>
    </fieldset>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
            Next
        </button>
    }

    @* ───── STEP 2 ───── *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select"
                             @bind-Value="model.PreferredDoctor"
                             @bind-Value:after="OnDoctorChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc.Name">@doc.Name</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.PreferredDoctor" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="date">Appointment Date</label>
                <InputDate id="date" class="form-control"
                           @bind-Value="model.AppointmentDate"
                           @bind-Value:after="OnDateChanged" />
                <ValidationMessage For="() => model.AppointmentDate" />
                @if (model.AppointmentDate.HasValue && model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
                {
                    <div class="text-danger">Date must be in the future.</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeslot">Time Slot</label>
                <InputSelect id="timeslot" class="form-select" @bind-Value="model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.TimeSlot" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="model.ReasonForVisit" />
                <ValidationMessage For="() => model.ReasonForVisit" />
                <small class="text-muted">@(model.ReasonForVisit?.Length ?? 0) / 500</small>
            </div>
        </fieldset>

        <div class="mt-3 d-flex gap-2">
            <button type="button" class="btn btn-outline-secondary" @onclick="BackToStep1">Back</button>
            <button type="button" class="btn btn-info" @onclick="CheckAvailability" disabled="@isChecking">
                @(isChecking ? "Checking…" : "Check Availability")
            </button>
            <button type="submit" class="btn btn-success" disabled="@(!availabilityChecked)">
                Book Appointment
            </button>
        </div>
    }
</EditForm>

@if (booked)
{
    <div class="alert alert-success mt-4" role="alert">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentModel model = new();
    private EditContext editContext = default!;
    private ValidationMessageStore messageStore = default!;

    private bool showStep2;
    private bool isChecking;
    private bool availabilityChecked;
    private bool booked;

    private List<DoctorInfo> doctors = [];
    private List<string> availableSlots = [];

    private static readonly string[] Step1Fields =
        [nameof(AppointmentModel.PatientName), nameof(AppointmentModel.Email),
         nameof(AppointmentModel.Phone), nameof(AppointmentModel.InsuranceProvider)];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        messageStore = new ValidationMessageStore(editContext);
        editContext.OnFieldChanged += (_, args) =>
        {
            messageStore.Clear(args.FieldIdentifier);
            availabilityChecked = false;
        };

        doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        messageStore.Clear();
        editContext.Validate();

        // Check only Step 1 fields
        bool step1Valid = !editContext.GetValidationMessages()
            .Any() || editContext.GetValidationMessages()
            .All(msg =>
            {
                // Accept if the only errors are from step-2 fields
                return false; // simplified — use field-level check below
            });

        // Field-level check for step 1
        step1Valid = Step1Fields.All(f =>
            !editContext.GetValidationMessages(editContext.Field(f)).Any());

        if (step1Valid)
        {
            showStep2 = true;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityChecked = false;
    }

    private async Task OnDoctorChanged()
    {
        availableSlots = [];
        model.TimeSlot = string.Empty;
        availabilityChecked = false;
        await LoadSlots();
    }

    private async Task OnDateChanged()
    {
        availableSlots = [];
        model.TimeSlot = string.Empty;
        availabilityChecked = false;
        await LoadSlots();
    }

    private async Task LoadSlots()
    {
        if (!string.IsNullOrEmpty(model.PreferredDoctor) && model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentSvc.GetAvailableSlotsAsync(
                model.PreferredDoctor, model.AppointmentDate.Value);
        }
    }

    private async Task CheckAvailability()
    {
        messageStore.Clear();
        availabilityChecked = false;

        // Client-side: date must be in the future
        if (model.AppointmentDate.HasValue && model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            messageStore.Add(editContext.Field(nameof(AppointmentModel.AppointmentDate)),
                "Date must be in the future.");
            editContext.NotifyValidationStateChanged();
            return;
        }

        // Validate step-2 annotations first
        editContext.Validate();
        var step2Fields = new[]
        {
            nameof(AppointmentModel.PreferredDoctor),
            nameof(AppointmentModel.AppointmentDate),
            nameof(AppointmentModel.TimeSlot),
            nameof(AppointmentModel.ReasonForVisit)
        };
        if (step2Fields.Any(f => editContext.GetValidationMessages(editContext.Field(f)).Any()))
        {
            return;
        }

        isChecking = true;
        try
        {
            var result = await AppointmentSvc.ValidatePatientAsync(
                model.Email, model.InsuranceProvider, model.PreferredDoctor, model.TimeSlot);

            if (!result.IsValid)
            {
                foreach (var err in result.Errors)
                {
                    messageStore.Add(editContext.Field(err.Key), err.Value);
                }
                editContext.NotifyValidationStateChanged();
            }
            else
            {
                availabilityChecked = true;
            }
        }
        finally
        {
            isChecking = false;
        }
    }

    private void HandleSubmit()
    {
        if (availabilityChecked)
        {
            booked = true;
        }
    }
}

