+        editContext.OnFieldChanged += (_, args) =>
+        {
+            messageStore.Clear(args.FieldIdentifier);
+            availabilityChecked = false;
+        };
+
+        doctors = await AppointmentSvc.GetDoctorsAsync();
+    }
+
+    private void ProceedToStep2()
+    {
+        messageStore.Clear();
+        editContext.Validate();
+
+        // Check only Step 1 fields
+        bool step1Valid = !editContext.GetValidationMessages()
+            .Any() || editContext.GetValidationMessages()
+            .All(msg =>
+            {
+                // Accept if the only errors are from step-2 fields
+                return false; // simplified — use field-level check below
+            });
+
+        // Field-level check for step 1
+        step1Valid = Step1Fields.All(f =>
+            !editContext.GetValidationMessages(editContext.Field(f)).Any());
+
+        if (step1Valid)
+        {
+            showStep2 = true;
+        }
+    }
+
+    private void BackToStep1()
+    {
+        showStep2 = false;
+        availabilityChecked = false;
+    }
+
+    private async Task OnDoctorChanged()
+    {
+        availableSlots = [];
+        model.TimeSlot = string.Empty;
+        availabilityChecked = false;
+        await LoadSlots();
+    }
+
+    private async Task OnDateChanged()
+    {
+        availableSlots = [];
+        model.TimeSlot = string.Empty;
+        availabilityChecked = false;
+        await LoadSlots();
+    }
+
+    private async Task LoadSlots()
+    {
+        if (!string.IsNullOrEmpty(model.PreferredDoctor) && model.AppointmentDate.HasValue)
+        {
+            availableSlots = await AppointmentSvc.GetAvailableSlotsAsync(
+                model.PreferredDoctor, model.AppointmentDate.Value);
+        }
+    }
+
+    private async Task CheckAvailability()
+    {
+        messageStore.Clear();
+        availabilityChecked = false;
+
+        // Client-side: date must be in the future
+        if (model.AppointmentDate.HasValue && model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
+        {
+            messageStore.Add(editContext.Field(nameof(AppointmentModel.AppointmentDate)),
+                "Date must be in the future.");
+            editContext.NotifyValidationStateChanged();
+            return;
+        }
+
+        // Validate step-2 annotations first
+        editContext.Validate();
+        var step2Fields = new[]
+        {
+            nameof(AppointmentModel.PreferredDoctor),
+            nameof(AppointmentModel.AppointmentDate),
+            nameof(AppointmentModel.TimeSlot),
+            nameof(AppointmentModel.ReasonForVisit)
+        };
+        if (step2Fields.Any(f => editContext.GetValidationMessages(editContext.Field(f)).Any()))
+        {
+            return;
+        }
+
+        isChecking = true;
+        try
+        {
+            var result = await AppointmentSvc.ValidatePatientAsync(
+                model.Email, model.InsuranceProvider, model.PreferredDoctor, model.TimeSlot);
+
+            if (!result.IsValid)
+            {
+                foreach (var err in result.Errors)
+                {
+                    messageStore.Add(editContext.Field(err.Key), err.Value);
+                }
+                editContext.NotifyValidationStateChanged();
+            }
+            else
+            {
+                availabilityChecked = true;
+            }
+        }
+        finally
+        {
+            isChecking = false;
+        }
+    }
+
+    private void HandleSubmit()
+    {
+        if (availabilityChecked)
+        {
+            booked = true;
+        }
+    }
+}
